-- ══════════════════════════════════════════════════════════════════
-- SYNTHETIC ALARM MASTER — ปลอดภัยต่อทรัพย์สินทางปัญญา
-- ══════════════════════════════════════════════════════════════════
-- สร้างขึ้นเพื่อทดแทนรายการรหัส alarm ของผู้ผลิตเครื่อง โดย:
--   ✔ รักษาโครงสร้างเชิงสถิติ (สัดส่วนชนิด A/W/E, ตระกูลความยาวรหัส,
--     การกระจาย subsystem, และ power-law ความถี่ของ process alarm)
--   ✘ ไม่มีรหัสจริงของผู้ผลิตแม้แต่รหัสเดียว (ตรวจชนแล้ว = 0)
--   ✘ ไม่มีข้อความคำอธิบายของผู้ผลิต — เขียนขึ้นใหม่ทั้งหมด
--
-- รหัสตระกูล 5 หลัก (81xxx) คือ process/quality alarm ที่ผูกความหมาย
-- กับคอลัมน์ใน ldi_data โดยตรง เพื่อให้ทดสอบ RCA correlation ได้จริง:
--     81101/81102 → air_vacuum      81201/81203/81204 → pe_*/je_*
--     81202       → scale_x/scale_y  81401 → scan_speed
--     81501       → temperature, humidity
-- ══════════════════════════════════════════════════════════════════

TRUNCATE TABLE public.ldi_alarm_ms_code;

ON CONFLICT (alarm_id) DO NOTHING;
